import { test, expect } from '@playwright/test';

test.describe('Payment Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/checkout');
  });

  test('should display order confirmation after successful payment', async ({ page }) => {
    await page.fill(getByLabel('Card Number'), '4111 1111 1111 1111');
    await page.fill(getByLabel('Expiry Date'), '12/25');
    await page.fill(getByLabel('CVC'), '123');
    await page.click(getByRole('button', { name: 'Pay Now' }));

    await expect(page.getByText('Payment Successful')).toBeVisible();
    await expect(page.getByText('Thank you for your order!')).toBeVisible();
  });

  test('should not display order confirmation after failed payment', async ({ page }) => {
    await page.fill(getByLabel('Card Number'), '4000 0000 0000 0002');
    await page.fill(getByLabel('Expiry Date'), '12/25');
    await page.fill(getByLabel('CVC'), '123');
    await page.click(getByRole('button', { name: 'Pay Now' }));

    await expect(page.getByText('Payment Failed')).toBeVisible();
    await expect(page.getByText('Please check your payment details and try again.')).toBeVisible();
  });
});
